import Foundation

/// Six runs of the lesson's program as patients to diagnose. / Шесть запусков программы урока как пациенты для диагноза.
struct TrainingDoctorState: Equatable {
    static let diagnoses = ["healthy", "rate_high", "rate_low", "labels_shuffled", "wrong_sign", "too_little_data"]
    /// A fixed order that starts with no giveaway. / Постоянный порядок, который не выдаёт ответы сразу.
    static let order = ["rate_low", "too_little_data", "healthy", "wrong_sign", "labels_shuffled", "rate_high"]

    private(set) var current = 0
    private(set) var solvedCases: Set<String> = []
    private(set) var wrongGuesses: Set<String> = []
    private(set) var firstTry = 0

    var currentCase: String { Self.order[current] }
    var curve: [(Double, Double)] { TrainingDoctorRecording.curves[currentCase] ?? [(0, 0)] }
    var isCurrentSolved: Bool { solvedCases.contains(currentCase) }
    var solvedCount: Int { solvedCases.count }
    var solved: Bool { solvedCases.count == Self.order.count }

    mutating func guess(_ diagnosis: String) {
        guard !isCurrentSolved else { return }
        if diagnosis == currentCase {
            if wrongGuesses.isEmpty { firstTry += 1 }
            solvedCases.insert(currentCase)
        } else {
            wrongGuesses.insert(diagnosis)
        }
    }

    mutating func next() {
        guard current + 1 < Self.order.count else { return }
        current += 1
        wrongGuesses = []
    }
}

